package com.casystem.onboarding.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.*;
@Service public class CryptoService{private final SecretKeySpec key;private final SecureRandom random=new SecureRandom();public CryptoService(@Value("${app.aes-key}")String k){byte[] b=k.getBytes(StandardCharsets.UTF_8);if(b.length!=32)throw new IllegalArgumentException("AES_KEY debe tener 32 bytes");key=new SecretKeySpec(b,"AES");}public String encrypt(String v){return v==null?null:Base64.getEncoder().encodeToString(encryptBytes(v.getBytes(StandardCharsets.UTF_8)));}public String decrypt(String v){return v==null?null:new String(decryptBytes(Base64.getDecoder().decode(v)),StandardCharsets.UTF_8);}public byte[] encryptBytes(byte[] data){try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] enc=c.doFinal(data);byte[] out=new byte[iv.length+enc.length];System.arraycopy(iv,0,out,0,iv.length);System.arraycopy(enc,0,out,iv.length,enc.length);return out;}catch(Exception e){throw new IllegalStateException("No se pudo cifrar",e);}}public byte[] decryptBytes(byte[] data){try{byte[] iv=Arrays.copyOfRange(data,0,12),enc=Arrays.copyOfRange(data,12,data.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return c.doFinal(enc);}catch(Exception e){throw new IllegalStateException("No se pudo descifrar",e);}}}